insert into public.project_states(id,workspace_id,name,stage,commercial_stage,status,priority,created_by,owner_user_id) values ('00000000-0000-4000-8000-00000000f020','00000000-0000-4000-8000-00000000f010','Setup fixture','predevelopment','predevelopment','active','medium','00000000-0000-4000-8000-00000000f001','00000000-0000-4000-8000-00000000f001');


insert into public.organizations(id,workspace_id,name,created_by) values ('00000000-0000-4000-8000-00000000f070','00000000-0000-4000-8000-00000000f010','Synthetic scope party','00000000-0000-4000-8000-00000000f001');
insert into public.document_records(id,project_state_id,package_key,category_key,document_type,title,owner_user_id) values ('00000000-0000-4000-8000-00000000f080','00000000-0000-4000-8000-00000000f020','predevelopment','product_program','predevelopment_product_program','Synthetic program','00000000-0000-4000-8000-00000000f001');
insert into public.document_revisions(id,document_record_id,revision_number,state,created_by,published_by,published_at,source_data,published_source_snapshot) values ('00000000-0000-4000-8000-00000000f081','00000000-0000-4000-8000-00000000f080',1,'published','00000000-0000-4000-8000-00000000f001','00000000-0000-4000-8000-00000000f001',now(),'{"programSummary":"Frozen synthetic requirement"}','{"programSummary":"Frozen synthetic requirement"}');
insert into public.authorization_records(id,project_state_id,outcome,actor_user_id) values ('00000000-0000-4000-8000-00000000f030','00000000-0000-4000-8000-00000000f020','approved','00000000-0000-4000-8000-00000000f001');
update public.project_states set stage='project_authorization_setup',commercial_stage='project_authorization_setup' where id='00000000-0000-4000-8000-00000000f020';
insert into public.project_states(id,workspace_id,name,stage,commercial_stage,status,priority,created_by,owner_user_id) select '00000000-0000-4000-8000-00000000f021',workspace_id,'Other scope project',stage,commercial_stage,status,priority,created_by,owner_user_id from public.project_states where id='00000000-0000-4000-8000-00000000f020';
insert into public.project_obligations(id,project_state_id,created_by) values ('00000000-0000-4000-8000-00000000f099','00000000-0000-4000-8000-00000000f021','00000000-0000-4000-8000-00000000f001');
select set_config('test.items','[{"id":"00000000-0000-4000-8000-00000000f090","type":"","requirement":"","sourceRevisionId":"","ownerUserId":"","dueDate":"","dueTrigger":"","dueRelationship":""}]',true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000f001","role":"authenticated"}',true);
select throws_ok($$select public.save_project_obligation_plan('00000000-0000-4000-8000-00000000f020',0,'00000000-0000-4000-8000-000000000001',current_setting('test.items')::jsonb)$$,'P0001','missing_setup_edit_permission','membership alone cannot edit');
reset role; insert into public.user_permission_overrides(workspace_id,user_id,permission_key,effect) values ('00000000-0000-4000-8000-00000000f010','00000000-0000-4000-8000-00000000f001','project.setup.edit','grant'); set local role authenticated;
select is(public.save_project_obligation_plan('00000000-0000-4000-8000-00000000f020',0,'00000000-0000-4000-8000-000000000001',current_setting('test.items')::jsonb)->>'version','1','partial plan persists');
select is(public.save_project_obligation_plan('00000000-0000-4000-8000-00000000f020',0,'00000000-0000-4000-8000-000000000001',current_setting('test.items')::jsonb)->>'savedVersion','1','lost response returns original version');
select throws_ok($$select public.save_project_obligation_plan('00000000-0000-4000-8000-00000000f020',0,'00000000-0000-4000-8000-000000000003',current_setting('test.items')::jsonb)$$,'P0001','obligation_version_conflict','stale save rejected');
select throws_ok($$select public.save_project_obligation_plan('00000000-0000-4000-8000-00000000f020',0,'00000000-0000-4000-8000-000000000001','[]')$$,'P0001','request_id_payload_mismatch','request payload immutable');
select throws_ok($$select public.save_project_obligation_plan('00000000-0000-4000-8000-00000000f020',1,'00000000-0000-4000-8000-000000000003',jsonb_set(current_setting('test.items')::jsonb,'{0,type}','"issued"'))$$,'P0001','invalid_obligation_type','type rejects issued');
select throws_ok($$select public.save_project_obligation_plan('00000000-0000-4000-8000-00000000f020',1,'00000000-0000-4000-8000-000000000003',jsonb_set(current_setting('test.items')::jsonb,'{0,type}','"gate_condition"'))$$,'P0001','invalid_obligation_type','type rejects gate_condition');
select throws_ok($$select public.save_project_obligation_plan('00000000-0000-4000-8000-00000000f020',1,'00000000-0000-4000-8000-000000000003',jsonb_set(current_setting('test.items')::jsonb,'{0,sourceRevisionId}','"00000000-0000-4000-8000-00000000ffff"'))$$,'P0001','invalid_obligation_source','sourceRevisionId rejects 00000000-0000-4000-8000-00000000ffff');
select throws_ok($$select public.save_project_obligation_plan('00000000-0000-4000-8000-00000000f020',1,'00000000-0000-4000-8000-000000000003',jsonb_set(current_setting('test.items')::jsonb,'{0,ownerUserId}','"00000000-0000-4000-8000-00000000f002"'))$$,'P0001','invalid_obligation_owner','ownerUserId rejects 00000000-0000-4000-8000-00000000f002');
select throws_ok($$select public.save_project_obligation_plan('00000000-0000-4000-8000-00000000f020',1,'00000000-0000-4000-8000-000000000003',jsonb_set(current_setting('test.items')::jsonb,'{0,dueDate}','"2026-02-30"'))$$,'P0001','invalid_obligation_date','dueDate rejects 2026-02-30');
select throws_ok($$select public.save_project_obligation_plan('00000000-0000-4000-8000-00000000f020',1,'00000000-0000-4000-8000-000000000003',jsonb_set(current_setting('test.items')::jsonb,'{0,dueDate}','"infinity"'))$$,'P0001','invalid_obligation_date','dueDate rejects infinity');
select throws_ok($$select public.save_project_obligation_plan('00000000-0000-4000-8000-00000000f020',1,'00000000-0000-4000-8000-000000000003',current_setting('test.items')::jsonb||current_setting('test.items')::jsonb)$$,'P0001','duplicate_obligation','duplicate identity rejected');
select throws_ok($$select public.save_project_obligation_plan('00000000-0000-4000-8000-00000000f020',1,'00000000-0000-4000-8000-000000000003','[]')$$,'P0001','obligation_removal_requires_governance','saved obligation cannot disappear');
select throws_ok($$select public.save_project_obligation_plan('00000000-0000-4000-8000-00000000f020',1,'00000000-0000-4000-8000-000000000003',current_setting('test.items')::jsonb||jsonb_set(current_setting('test.items')::jsonb,'{0,id}','"00000000-0000-4000-8000-00000000f099"'))$$,'P0001','obligation_wrong_project','foreign identity rejected');
select set_config('test.items',jsonb_set(current_setting('test.items')::jsonb,'{0}',(current_setting('test.items')::jsonb->0)||'{"type":"permit","requirement":"Obtain building permit","sourceRevisionId":"00000000-0000-4000-8000-00000000f081","ownerUserId":"00000000-0000-4000-8000-00000000f001","dueDate":"2026-10-01","dueTrigger":"Before excavation"}')::text,true);
select is(public.save_project_obligation_plan('00000000-0000-4000-8000-00000000f020',1,'00000000-0000-4000-8000-000000000003',current_setting('test.items')::jsonb)->>'planComplete','false','two deadlines require explicit relationship');
select set_config('test.items',jsonb_set(current_setting('test.items')::jsonb,'{0,dueRelationship}','"Before excavation and no later than the date"')::text,true);
select is(public.save_project_obligation_plan('00000000-0000-4000-8000-00000000f020',2,'00000000-0000-4000-8000-000000000004',current_setting('test.items')::jsonb)->>'planComplete','true','complete sourced plan recorded');
select is(public.read_project_obligation_plan('00000000-0000-4000-8000-00000000f020')->>'satisfactionVerified','false','plan never proves satisfaction');
select is(public.read_project_obligation_plan('00000000-0000-4000-8000-00000000f020')->>'authorizationRecordId','00000000-0000-4000-8000-00000000f030','frozen authorization retained');
select is((select count(*)::integer from public.project_obligations where project_state_id='00000000-0000-4000-8000-00000000f020'),1,'one durable obligation across versions');
select is((select count(*)::integer from public.project_obligation_plan_versions),3,'one version per successful request');
select is((select references_snapshot->'revisions'->0->'payload'->>'programSummary' from public.project_obligation_plan_versions where version=3),'Frozen synthetic requirement','source payload frozen');
select ok(public.read_project_setup('00000000-0000-4000-8000-00000000f020')->'unmet' ? 'permits','preparation retains permit blocker');
select throws_ok($$select public.decide_project_gate01('00000000-0000-4000-8000-00000000f020',0,'00000000-0000-4000-8000-000000000006',null,'go','Synthetic','[]')$$,'P0001','obligation_plan_review_required','go cannot bypass review');
select throws_ok($$select public.decide_project_gate01('00000000-0000-4000-8000-00000000f020',0,'00000000-0000-4000-8000-000000000006',null,'conditional_go','Synthetic','[]')$$,'P0001','obligation_plan_review_required','conditional_go cannot bypass review');
select public.save_project_setup('00000000-0000-4000-8000-00000000f020',0,'00000000-0000-4000-8000-000000000009',(select jsonb_agg(jsonb_build_object('requirement',k,'state','satisfied','details','Forged checklist','evidenceReference','fake:approval','accountableUserId','00000000-0000-4000-8000-00000000f001','materialBlocker',false)) from unnest(array['contracting_party','contract_review','scope','commercial_terms','contractual_risks','permits','leadership','budget_basis','delivery_folder','access','communications','controls']) k));
select is((select e->>'state' from public.project_setup_versions s cross join lateral jsonb_array_elements(s.evidence) e where e->>'requirement'='permits'),'unresolved','generic checklist cannot overwrite obligation evidence');
reset role;
select throws_ok($$update public.project_obligation_plan_versions set items='[]'$$,'P0001','setup_history_is_immutable','history immutable');
select throws_ok($$delete from public.project_obligations$$,'P0001','setup_history_is_immutable','identity immutable');
update public.project_states set archived_at=now() where id='00000000-0000-4000-8000-00000000f020'; set local role authenticated;
select is(public.save_project_obligation_plan('00000000-0000-4000-8000-00000000f020',2,'00000000-0000-4000-8000-000000000004',current_setting('test.items')::jsonb)->>'savedVersion','3','archive still permits exact retry recovery');
select throws_ok($$select public.save_project_obligation_plan('00000000-0000-4000-8000-00000000f020',3,'00000000-0000-4000-8000-000000000005',current_setting('test.items')::jsonb)$$,'P0001','obligation_edit_not_allowed','archive rejects new save');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000f002","role":"authenticated"}',true);
select is((select count(*)::integer from public.project_obligation_plan_versions),0,'outsider cannot read history');
select is((select count(*)::integer from public.project_obligations),0,'outsider cannot read identities');
select throws_ok($$select public.read_project_obligation_plan('00000000-0000-4000-8000-00000000f020')$$,'P0001','project_state_not_found_or_access_denied','outsider RPC denied');
select ok(not has_function_privilege('anon','public.save_project_obligation_plan(uuid,integer,uuid,jsonb)','execute'),'anonymous command denied');
select * from finish(); rollback;
